@W.span('native_roundtrip', 83, runtime=False)
def _tunggu_hasil(dirpath: Path, request_id: str, batas_detik: float) -> HasilPerintah:
    clock = result_wait_clock.get() or time.monotonic
    cancelled = result_wait_cancel.get()
    batas = clock() + batas_detik
    hasil_path = dirpath / NAMA_RESULT
    cut = False
    while clock() < batas:
        isi = _baca_json(hasil_path)
        if isi is not None and isi.get('request_id') == request_id:
            return _hasil_dari_envelope(isi, request_id)
        if cancelled is not None and (not cut) and cancelled():
            cut, batas = (True, min(batas, clock() + CANCEL_WAIT_GRACE_S))
        W.call('poll', 84, time.sleep, JEDA_POLL_DETIK)
    if cut:
        return HasilPerintah(status=TIDAK_PASTI, sukses=False, request_id=request_id, alasan='cancelled_before_result; aksi mungkin terjadi. JANGAN ulangi otomatis')
    return HasilPerintah(status=TIDAK_PASTI, sukses=False, request_id=request_id, alasan='hasil belum datang; aksi mungkin terjadi. JANGAN ulangi otomatis; periksa log SMAPI')

wait_functions.arti_runtime.experience_facts:_place_sou:
@_offer_memoized
def _place_sources(catalog):
    sources = {p: 'location_entered:' + p for p in entered(catalog) if isinstance(p, str)}
    for p in native_rows((catalog.get('world_graph') or {}).get('places', ())):
        if isinstance(p, Mapping) and p.get('id') and (p.get('experience_known') is True):
            sources.setdefault(p['id'], p.get('fact_source', 'native_experience'))
    for text, ref, evidence in text_evidence(catalog):
        for place in native_rows((catalog.get('world_graph') or {}).get('places', ())):
            if not isinstance(place, Mapping):
                continue
            identity = place.get('id')
            if identity in sources:
                continue
            explicit = evidence.get('subject') == identity and evidence.get('kind') in ('place_learned', 'door_seen', 'sign_read')
            names = (identity, place.get('label'))
            if identity and (explicit or any((isinstance(name, str) and name and re.search('(?<!\\w)' + re.escape(name) + '(?!\\w)', str(text), re.I) for name in names))):
                sources.setdefault(identity, ref)
    return sources

wait_functions.arti_runtime.use_places:travel:
def travel(context, facts):
    """Startable trips to places where what she carries can be used, with native purpose."""
    from arti_runtime.experience_facts import place_sources
    inventory = context.get('inventory') or ()
    kinds = carried_uses(inventory)
    if not kinds:
        return []
    known = place_sources(context.get('world_knowledge') or {})
    here = facts.location
    graph = (context.get('world_knowledge') or {}).get('world_graph') or {}
    places = {p.get('id'): p for p in native_rows(graph.get('places', ())) if isinstance(p, dict) and p.get('id')}
    rows = []
    for option in travel_options(context, here, now=facts.time_of_day):
        loc = option['location']
        if loc not in known:
            continue
        used = matches(places.get(loc) or {}, kinds)
        if not used:
            continue
        rows.append(dict(option, use_kinds=used))
    return rows

wait_functions.arti_runtime.room_facts:page:
def page(context, facts, policy, calls):
    """ADR 206: bag/container decisions need destinations even before the bag fills.

    Travel admission does not determine whether a known facility is a fact. A closed
    counter still exists, and the row must say that its acceptance/hours are unknown.
    """
    from arti_stardew_live7 import goods_facts, hard_dispose_refusal
    from arti_runtime.travel_time import estimate
    from arti_runtime.use_places import carried_uses, matches, purpose_text
    from scripts.live7.interactions import ordinary_targets
    if not (need_space(facts, policy) or any((c.name == 'inventori' for c in calls)) or any((r.get('kind') in LOCAL for r in ordinary_targets(context)))):
        return _use_page(context, facts, policy, calls)
    goods = goods_facts(context)
    sell = [r for r in goods if hard_dispose_refusal(r) is None]
    rows = []
    graph = (context.get('world_knowledge') or {}).get('world_graph') or {}
    for place in places(context):
        if place.get('experience_known') is False:
            continue
        loc = place['id']
        path = [] if loc == facts.location else place.get('motor_route') or place.get('route')
        if path is None:
            continue
        distance_info = estimate(facts.location, path, policy)
        distance = distance_info['minutes']
        native = place.get('facts') or ()
        sinks = []
        chests = [r for r in getattr(getattr(policy, 'chest_memory', None), 'rows', {}).values() if r['location'] == loc]
        if loc in context.get('seen_chest_places', ()) or chests:
            tiles = ','.join(('%s,%s' % tuple(r['tile']) for r in chests))
            sinks.append('Peti yang pernah dilihat%s: isi tas, termasuk alat; ruang/penerimaan dicek saat buka' % (' ' + tiles if tiles else ''))
        if any((str(f).startswith('shipping bin:') for f in native)):
            accepted = [r for r in sell if r.get('shippable') is not False and r.get('ship_policy') in (None, 'ok')]
            accepted = [dict(r, unit_price=None) if r.get('price_source') == 'shop' else r for r in accepted]
            sinks.append('Kotak pengiriman: %s; %s; penerimaan native dicek di kotak' % (item_terms(accepted, prices=True), shipping_value(accepted)))
        if any((str(f).startswith('shop counter ') for f in native)):
            refused = getattr(policy, 'shop_refused', {}).get(loc, ())
            candidates = [r for r in sell if r.get('qualified_item_id') not in refused]
            candidates = [dict(r, unit_price=None) if r.get('price_source') == 'shop' and r.get('price_location') != loc else r for r in candidates]
            sinks.append('konter: %s; penerimaan/harga: menu toko' % item_terms(candidates, prices=True))
        if sinks:
            sinks.extend((purpose_text(k) for k in matches(place, carried_uses(context.get('inventory'))) if k not in ('bin', 'shop')))
            arg = 'home' if loc == graph.get('home') else location_arg(loc)
            rows.append(dict(tujuan=arg, jalan_menit=distance, guna='; '.join(sinks), dasar='antar peta; ' + distance_info['basis'] + ('; langkah lokal belum ditaksir' if not distance else ''), **{'akses': str(place['locked'])} if place.get('locked') else {}))
    sink_args = {r['tujuan'] for r in rows}
    for original in _use_page(context, facts, policy, calls):
        if original['tujuan'] not in sink_args:
            rows.append(original)
        elif original.get('mengapa'):
            next((r for r in rows if r['tujuan'] == original['tujuan']))['mengapa'] = original['mengapa']
    return rows

wait_functions.arti_runtime.room_facts:_use_page:
def _use_page(context, facts, policy, calls):
    from arti_runtime.travel_time import estimate
    from scripts.live7.interactions import ordinary_targets
    offered = {(c.name, c.arg) for c in calls}
    rows = []
    for o in destinations(context, facts, policy):
        if ('pergi_ke', o['arg']) not in offered:
            continue
        purposes = [text for _, text in o['activities'] if text.startswith(ROOM_PREFIX)]
        eta = estimate(facts.location, o['route'], policy)
        rows.append(dict(tujuan=o['arg'], guna=' '.join(purposes), jalan_menit=eta['minutes'], dasar=eta['basis']))
    if need_space(facts, policy):
        for r in ordinary_targets(context):
            kind, ref = (r.get('kind'), r.get('ref'))
            if kind not in LOCAL or ('aksi', ref) not in offered:
                continue
            rows.append(dict(tujuan=ref, guna=r.get('label') or LOCAL[kind], jalan_menit=0, dasar='di peta ini'))
    rows.extend(withheld(context, facts, policy))
    return rows

wait_functions.arti_runtime.room_facts:destinations:
def destinations(context, facts, policy):
    from arti_runtime.experience_facts import place_sources
    from arti_runtime.use_places import travel as use_travel
    known = place_sources(context.get('world_knowledge') or {})
    space = []
    if need_space(facts, policy):
        space = [o for o in travel_options(context, facts.location, now=facts.time_of_day) if o['location'] in known and any((text.startswith(('Peti yang pernah dilihat:', 'Kotak pengiriman:', 'Konter:')) for _, text in o['activities']))]
    use = []
    for option in use_travel(context, facts):
        texts = [('fact', purpose_text(k)) for k in option.get('use_kinds') or ()]
        use.append(dict(option, activities=list(option.get('activities') or ()) + texts))
    return _merge(space, use)

wait_functions.arti_runtime.room_facts:withheld:
def withheld(context, facts, policy):
    """Commerce and use-places she knows, with the native reason they are not a startable trip."""
    from arti_runtime.experience_facts import place_sources
    from arti_runtime.use_places import carried_uses, matches
    known = place_sources(context.get('world_knowledge') or {})
    offered = {o['location'] for o in destinations(context, facts, policy)}
    kinds = carried_uses(context.get('inventory'))
    rows = []
    for p in places(context):
        if p['id'] not in known or p['id'] == facts.location or p['id'] in offered:
            continue
        purposes = list(commerce_purpose(p, context))
        if not need_space(facts, policy):
            purposes = []
        purposes.extend((purpose_text(k) for k in matches(p, kinds) if purpose_text(k) not in purposes))
        if not purposes:
            continue
        why = p.get('locked')
        if why is None and p.get('go_to_available') is False:
            why = 'go_to unavailable'
        if why is None and (not p.get('route')):
            why = 'route unknown'
        rows.append(dict(tujuan=location_arg(p['id']), guna=' '.join(purposes), mengapa=str(why) if why else 'tidak terjangkau'))
    return rows
